 30 | function resolveDispatcher() {
 31 |   const dispatcher = ReactSharedInternals.H;
 32 |   if (__DEV__) {
 33 |     if (dispatcher === null) {
 34 |       console.error(
 35 |         'Invalid hook call. Hooks can only be called inside of the body of a function component. This could happen for' +
 36 |           ' one of the following reasons:\n' +
 37 |           '1. You might have mismatching versions of React and the renderer (such as React DOM)\n' +
 38 |           '2. You might be breaking the Rules of Hooks\n' +
 39 |           '3. You might have more than one copy of React in the same app\n' +
 40 |           'See https://react.dev/link/invalid-hook-call for tips about how to debug and fix this problem.',
 41 |       );
 42 |     }
 43 |   }
 44 |   // Will result in a null access error if accessed outside render phase. We
 45 |   // intentionally don't throw our own error because this is in a hot path.
 46 |   // Also helps ensure this is inlined.
 47 |   return ((dispatcher: any): Dispatcher);
 48 | }
